# moon_embedded.py
# Tekstura Księżyca 300x300 zaszyta w tym pliku.
# Uruchom ten plik na Pico w Thonny.
# Utworzy on w pamięci flash Pico plik "moon.raw".
# Po udanej instalacji można usunąć ten plik z Pico.
#
# Format moon.raw:
# 300 x 300 pikseli, 8-bit grayscale = 90 000 bajtów.
# Dane w tym pliku .py są zlib-compressed + Base64.

import ubinascii
import uzlib

WIDTH = 300
HEIGHT = 300
RAW_SIZE = 90000

DATA_B64 = ""

def install():
    compressed = ubinascii.a2b_base64(DATA_B64)
    del DATA_B64

    import io
    source = io.BytesIO(compressed)
    decompressor = uzlib.DecompIO(source)

    with open("moon.raw", "wb") as out:
        total = 0
        while total < RAW_SIZE:
            chunk = decompressor.read(4096)
            if not chunk:
                break
            out.write(chunk)
            total += len(chunk)

    if total != RAW_SIZE:
        raise RuntimeError("Bledny rozmiar tekstury: " + str(total))

    print("OK - moon.raw zapisany:", total, "bajtow")

install()
